//! Release notes and links (ports of desktop/release-history.cjs and release-links.cjs, and the release-info
//! handler of main.cjs).
//!
//! The welcome splash shows the bundled notes of the installed version (`desktop/release-info.json`, generated by
//! `npm run release:prepare`), offline. Recent releases come from the fixed public endpoint: one shared request at a
//! time, an 8 second limit, no redirects, at most 512 KB, cached for five minutes, and only well-formed stable
//! entries, newest first.

use std::sync::atomic::{AtomicBool, Ordering};
use std::time::{Duration, Instant};

use futures_util::StreamExt;
use serde::Serialize;
use serde_json::Value;
use tauri::AppHandle;
use tokio::sync::Mutex;

use super::Failure;

pub const RELEASES_URL: &str = "https://github.com/filippocalippo/styk-animate-releases/releases/latest";
pub const DONATE_URL: &str = "https://ko-fi.com/Q5Q41WY7QC";
const ENDPOINT: &str = "https://stykanimate.com/api/v1/releases";
const LIMIT: usize = 512 * 1024;
const RELEASE_INFO: &str = include_str!("../../../../../desktop/release-info.json");

static STARTUP_SHOWN: AtomicBool = AtomicBool::new(false);

/// `styk:release-info`: the installed version's notes. At start (`startup`) only once per process, so a page that
/// loads again does not show the splash again.
#[tauri::command]
pub fn release_info(app: AppHandle, startup: Option<bool>) -> Result<Value, Failure> {
    let startup = startup.unwrap_or(false);
    if startup && STARTUP_SHOWN.swap(true, Ordering::SeqCst) {
        return Ok(Value::Null);
    }
    let mut info: Value = serde_json::from_str(RELEASE_INFO).map_err(|e| Failure::plain(e.to_string()))?;
    if let Some(object) = info.as_object_mut() {
        object.insert("version".into(), app.package_info().version.to_string().into());
    }
    Ok(info)
}

/// One published release's notes.
#[derive(Debug, Clone, Serialize, PartialEq)]
pub struct Release {
    pub version: String,
    pub markdown: String,
}

fn version_parts(version: &str) -> Option<[u32; 3]> {
    let mut parts = version.split('.');
    let mut out = [0u32; 3];
    for slot in &mut out {
        let part = parts.next()?;
        if part.is_empty() || part.len() > 3 || !part.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        *slot = part.parse().ok()?;
    }
    parts.next().is_none().then_some(out)
}

/// The releases a response lists: the first 20 entries, well-formed stable ones only, each version once, newest
/// first, notes cut at 16,000 characters.
pub fn parse_releases(text: &str) -> Result<Vec<Release>, Failure> {
    let value: Value = serde_json::from_str(text).map_err(|e| Failure::plain(e.to_string()).named("SyntaxError"))?;
    let Some(list) = value.get("releases").and_then(Value::as_array) else {
        return Err(Failure::key("desktop.releaseHistory.errors.invalidReleaseHistory"));
    };
    let mut seen = std::collections::HashSet::new();
    let mut releases: Vec<Release> = list
        .iter()
        .take(20)
        .filter_map(|item| {
            let version = item.get("version")?.as_str()?;
            version_parts(version)?;
            if item.get("channel")?.as_str()? != "stable" {
                return None;
            }
            let notes = item.get("notes")?.as_str()?;
            if !seen.insert(version.to_owned()) {
                return None;
            }
            // JavaScript's slice counts UTF-16 units.
            let units: Vec<u16> = notes.encode_utf16().take(16000).collect();
            Some(Release { version: version.to_owned(), markdown: String::from_utf16_lossy(&units) })
        })
        .collect();
    releases.sort_by_key(|release| std::cmp::Reverse(version_parts(&release.version)));
    if releases.is_empty() {
        return Err(Failure::key("desktop.releaseHistory.errors.noReleaseHistoryAvailable"));
    }
    Ok(releases)
}

async fn fetch_releases() -> Result<Vec<Release>, Failure> {
    let unavailable = || Failure::key("desktop.releaseHistory.errors.releaseHistoryUnavailable");
    let _ = rustls::crypto::ring::default_provider().install_default();
    let client = reqwest::Client::builder()
        .redirect(reqwest::redirect::Policy::none())
        .timeout(Duration::from_secs(8))
        .build()
        .map_err(|_| unavailable())?;
    let response = client.get(ENDPOINT).send().await.map_err(|_| unavailable())?;
    if !response.status().is_success() || response.content_length().is_some_and(|n| n as usize > LIMIT) {
        return Err(unavailable());
    }
    let mut body = Vec::new();
    let mut stream = response.bytes_stream();
    while let Some(part) = stream.next().await {
        let part = part.map_err(|_| unavailable())?;
        if body.len() + part.len() > LIMIT {
            return Err(Failure::key("desktop.releaseHistory.errors.releaseHistoryIsTooLarge"));
        }
        body.extend_from_slice(&part);
    }
    parse_releases(&String::from_utf8_lossy(&body))
}

static HISTORY: Mutex<Option<(Instant, Vec<Release>)>> = Mutex::const_new(None);

/// `styk:release-history`.
#[tauri::command]
pub async fn release_history() -> Result<Vec<Release>, Failure> {
    // Held across the request: a second caller waits for the first one's answer instead of asking again.
    let mut cache = HISTORY.lock().await;
    if let Some((expires, releases)) = cache.as_ref()
        && Instant::now() < *expires
    {
        return Ok(releases.clone());
    }
    let releases = fetch_releases().await?;
    *cache = Some((Instant::now() + Duration::from_secs(300), releases.clone()));
    Ok(releases)
}

/// `styk:donate`: the Ko-fi page, in the system browser.
#[tauri::command]
pub fn donate() -> Result<(), Failure> {
    super::open_external(DONATE_URL)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn keeps_well_formed_stable_releases_newest_first() {
        let text = r#"{"releases":[
            {"version":"1.2.0","channel":"stable","notes":"a"},
            {"version":"1.10.0","channel":"stable","notes":"b"},
            {"version":"1.3.0","channel":"beta","notes":"c"},
            {"version":"1.2.0","channel":"stable","notes":"again"},
            {"version":"1.2","channel":"stable","notes":"d"},
            {"version":"1.2.3.4","channel":"stable","notes":"e"},
            {"version":"1.2.4","channel":"stable","notes":7}
        ]}"#;
        let releases = parse_releases(text).unwrap();
        assert_eq!(releases.iter().map(|r| r.version.as_str()).collect::<Vec<_>>(), ["1.10.0", "1.2.0"]);
        assert_eq!(releases[1].markdown, "a");
        assert_eq!(parse_releases(r#"{"releases":[]}"#).unwrap_err().message_key.as_deref(), Some("desktop.releaseHistory.errors.noReleaseHistoryAvailable"));
        assert_eq!(parse_releases(r#"{}"#).unwrap_err().message_key.as_deref(), Some("desktop.releaseHistory.errors.invalidReleaseHistory"));
        let long = format!(r#"{{"releases":[{{"version":"1.0.0","channel":"stable","notes":"{}"}}]}}"#, "x".repeat(20000));
        assert_eq!(parse_releases(&long).unwrap()[0].markdown.len(), 16000);
    }

    #[test]
    fn the_bundled_release_info_parses() {
        let info: Value = serde_json::from_str(RELEASE_INFO).unwrap();
        assert!(info.get("notes").is_some());
    }
}
